import{_ as o,r as s,o as l,c as p,e as a,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Selectable Column - October CMS - 4.x","titleTemplate":false,"description":"List Column","frontmatter":{"subtitle":"List Column","shortname":"Selectable"},"headers":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}],"relativePath":"4.x/element/lists/column-selectable.md","filePath":"4.x/element/lists/column-selectable.md"}'),r={name:"4.x/element/lists/column-selectable.md"};function d(u,e,k,h,g,m){const n=s("pre-heading"),t=s("post-heading");return l(),p("div",null,[a(n),e[0]||(e[0]=c("h1",null,"Selectable Column",-1)),a(t),e[1]||(e[1]=i(`<p><code>selectable</code> - takes the column value and matches it to the value in the record&#39;s available options. Take the following array as an example, if the record value is set to <code>open</code> then the <strong>Open</strong> value is displayed in the column.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;open&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Open&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;closed&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Closed&#39;</span><span class="token punctuation">]</span>
</code></pre></div><p>The available options are defined based on <a href="./../define-options.html">dropdown options</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">status</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Status
    <span class="token key atrule">type</span><span class="token punctuation">:</span> selectable
</code></pre></div><p>The following properties are supported.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>options</strong></td><td>available options for the dropdown, as an array.</td></tr><tr><td><strong>optionsMethod</strong></td><td>take options from a method defined on the model or as a static method, eg <code>Class::method</code>.</td></tr><tr><td><strong>optionsPreset</strong></td><td>take options from a <a href="./../define-options.html">preset list of defined options</a>.</td></tr></tbody></table></div><p>The <code>options</code> value can specify options explicitly as an array.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">status</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Status
    <span class="token key atrule">type</span><span class="token punctuation">:</span> selectable
    <span class="token key atrule">options</span><span class="token punctuation">:</span>
        <span class="token key atrule">pending</span><span class="token punctuation">:</span> Pending
        <span class="token key atrule">active</span><span class="token punctuation">:</span> Active
</code></pre></div><p>The <code>optionsPreset</code> can be used to extract the value from a <a href="./../define-options.html">options preset definition</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">icon</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Icon
    <span class="token key atrule">type</span><span class="token punctuation">:</span> selectable
    <span class="token key atrule">optionsPreset</span><span class="token punctuation">:</span> phosphorIcons
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../define-options.html">Defining Options</a></li><li><a href="./../form/field-dropdown.html">Dropdown Form Field</a></li></ul></div>`,12))])}const b=o(r,[["render",d]]);export{y as __pageData,b as default};
